using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.CourseChanges;using TechnifyERP.Application.Enrollments;
namespace TechnifyERP.Areas.Student;
[Area("Student"),Authorize(Roles="Student")]public sealed class CourseChangesController(ICourseChangeService changes,IEnrollmentService enrollments):Controller
{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Courses=(await enrollments.GetStudentEnrollmentsAsync(Id,ct)).Where(x=>x.Status==TechnifyERP.Domain.Enums.EnrollmentStatus.Approved).Select(x=>new SelectListItem($"{x.CourseCode} - {x.CourseName}",x.CourseId.ToString()));ViewBag.Targets=(await enrollments.GetAvailableCoursesAsync(Id,ct)).Select(x=>new SelectListItem($"{x.Code} - {x.Name} (Rs. {x.MonthlyFee:N2})",x.Id.ToString()));return View(await changes.GetForStudentAsync(Id,ct));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(int fromCourseId,int toCourseId,string reason,CancellationToken ct){var r=await changes.CreateAsync(Id,fromCourseId,toCourseId,reason,ct);TempData[r==CourseChangeActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==CourseChangeActionResult.Success?"Course change request admin ko bhej di gayi.":"Request valid nahi hai ya pending request already maujood hai.";return RedirectToAction(nameof(Index));}string Id=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;}
